import { getJson, postJson } from '../../api/http';
import { sheetKey } from '../sheet/api';

/** A member of a pool, a person (`personId`) or another pool (`poolId`, `name` its name), with their share
 *  percent (two decimals); a `retired` member's share counts as 0.00 toward the pool's total. `cut` is
 *  their cut of the pool's pot (two decimals; a retired member's 0.00, the remainder going to the largest
 *  share), "" when the pool is unbalanced or has no pot. A pool that is a member of none cuts the sheet's
 *  pot; a member pool cuts its own cut in the pool above. */
export type PoolMember = { personId: number | null; poolId: number | null; name: string; share: string; retired: boolean; cut: string };

/** A pool on the sheet: its members in the order added, the total of their shares and whether that
 *  total is exactly 100.00 (`balanced`). */
export type Pool = { id: number; sheetId: string; name: string; members: PoolMember[]; totalShare: string; balanced: boolean;
  parentId: number | null };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/pools`;

export const poolsKey = (sheetId: string) => [...sheetKey(sheetId), 'pools'] as const;

/** The sheet's pools, in the order they were added. */
export function listPools(sheetId: string): Promise<Pool[]> {
  return getJson<Pool[]>(base(sheetId));
}

/** Add a pool (name trimmed); refused (rejects) for a blank name or one already used on the sheet. */
export function addPool(sheetId: string, by: string, name: string): Promise<Pool[]> {
  return postJson<Pool[]>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, { name });
}

/** A pool member to add: a person or another pool of the sheet. */
export type MemberRef = { personId: number } | { memberPoolId: number };

/** Add a person or another pool to a pool with a share percent; refused (rejects) for a person already in
 *  the pool, a share that is not more than 0.00 and at most 100.00 with at most two decimals, or a pool
 *  already a member of a pool, that would contain itself or make a chain of pools more than three deep. */
export function addPoolMember(sheetId: string, by: string, poolId: number, member: MemberRef, share: string): Promise<Pool[]> {
  return postJson<Pool[]>(`${base(sheetId)}/${poolId}/members?by=${encodeURIComponent(by)}`, { ...member, share });
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { Pools } from './Pools';

export const contribution = SheetBody.fill({ order: 9.7, Component: Pools });
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { listPeople, peopleKey } from '../people/api';
import type { Person } from '../people/api';
import { addPool, addPoolMember, listPools, poolsKey } from './api';
import type { MemberRef, Pool } from './api';

/** The sheet's pools and a form to add one (name trimmed; a blank or repeated one refused). Each pool
 *  lists its members with their shares, its total share (a retired member's counting as 0.00) and
 *  whether it is balanced (exactly 100.00), each member's cut of
 *  the pool's pot (blank when unbalanced or no pot), and adds a member — a person or another pool, listed
 *  as pool:<name> — from its row. A pool that is a member of another cuts its cut there. */
export function Pools({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const pools = useQuery({ queryKey: poolsKey(sheetId), queryFn: () => listPools(sheetId) });
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const [name, setName] = useState('');

  const save = useMutation({
    mutationFn: (input: string) => addPool(sheetId, user, input),
    onSuccess: (data) => {
      setName('');
      queryClient.setQueryData(poolsKey(sheetId), data);
    },
  });

  const submitOnce = useSubmitOnce();

  return (
    <section>
      <h3>Pools</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const input = name;
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(input);
          });
        }}
      >
        <input data-testid="pool-form-name" placeholder="Pool name" value={name}
          onChange={(e) => {
            setName(e.target.value);
            save.reset();
          }} />{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={save.isPending}>
          Add pool
        </button>
        {save.isError && (
          <span data-testid="pool-form-error">A pool needs a name not already used on the sheet.</span>
        )}
      </form>
      <ul>
        {(pools.data ?? []).map((p) => (
          <PoolRow key={p.id} sheetId={sheetId} user={user} pool={p} people={people.data ?? []} pools={pools.data ?? []} />
        ))}
      </ul>
    </section>
  );
}

/** The select's value for a member: a person's id, or pool:<id> for a pool. */
function memberRef(value: string): MemberRef {
  return value.startsWith('pool:') ? { memberPoolId: Number(value.slice(5)) } : { personId: Number(value) };
}

function PoolRow({ sheetId, user, pool, people, pools }: { sheetId: string; user: string; pool: Pool; people: Person[]; pools: Pool[] }) {
  const queryClient = useQueryClient();
  const [member, setMember] = useState('');
  const [share, setShare] = useState('');

  const add = useMutation({
    mutationFn: (input: { member: MemberRef; share: string }) =>
      addPoolMember(sheetId, user, pool.id, input.member, input.share),
    onSuccess: (data) => {
      setMember('');
      setShare('');
      queryClient.setQueryData(poolsKey(sheetId), data);
    },
  });

  const submitOnce = useSubmitOnce();

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong>{' '}
      total <span data-testid="pool-total-share">{pool.totalShare}</span>{' '}
      balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li key={m.poolId !== null ? `pool-${m.poolId}` : m.personId}
            data-testid={`pool-member-${pool.name}-${m.poolId !== null ? `pool-${m.name}` : m.personId}`}>
            {m.poolId !== null ? `pool:${m.name}` : m.name}{m.retired ? ' (retired)' : ''} share <span data-testid="pool-share">{m.share}</span>{' '}
            cut <span data-testid="pool-cut">{m.cut}</span>
          </li>
        ))}
      </ul>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const input = { member: memberRef(member), share };
          submitOnce(() => {
            add.reset();
            return add.mutateAsync(input);
          });
        }}
      >
        <select data-testid="pool-member-select" value={member}
          onChange={(e) => {
            setMember(e.target.value);
            add.reset();
          }}>
          <option value="">Member…</option>
          {people.map((person) => (
            <option key={person.id} value={String(person.id)}>{person.name}</option>
          ))}
          {pools.map((p) => (
            <option key={`pool-${p.id}`} value={`pool:${p.id}`}>{`pool:${p.name}`}</option>
          ))}
        </select>{' '}
        <input data-testid="pool-member-share" placeholder="Share %" value={share}
          onChange={(e) => {
            setShare(e.target.value);
            add.reset();
          }} />{' '}
        <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
          Add member
        </button>
        {add.isError && (
          <span data-testid="pool-error">The member could not be added: a person not already in the pool, or a pool not already in one that keeps chains acyclic and at most three deep, with a share more than 0.00 and at most 100.00 (two decimals).</span>
        )}
      </form>
    </li>
  );
}
